{"filePath": "/Users/dwahl/Scripts/pantoken/docs/scripts/stage-create-pantoken-app-domain.ts", "content": "/**
 * Publish the `create-pantoken-app` skill as the root index of the `create.pantoken.app`
 * submodule (`ai/create-pantoken-app-site`), so `https://create.pantoken.app` serves the skill's
 * raw content directly at "/" — a URL-hack shortcut for agent CLIs that avoids the
 * `/create-pantoken-app.md` path used on the main docs site. See
 * `stage-create-pantoken-app-skill.ts` for the sibling copy served at `pantoken.app`.
 *
 * This only stages the working tree inside the submodule; committing and pushing the submodule
 * repo (which triggers the GitHub Pages redeploy) is a separate, manual step.
 */
import { copyFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const docsRoot = join(import.meta.dirname, "..");
const source = join(docsRoot, "../ai/pantoken-ai/skills/create-pantoken-app/SKILL.md");
const siteDir = join(docsRoot, "../ai/create-pantoken-app-site");

mkdirSync(siteDir, { recursive: true });
// .html extension so GitHub Pages resolves it as the directory index at "/"; content stays plain text.
copyFileSync(source, join(siteDir, "index.html"));
// .md alias for parity with the pantoken.app/create-pantoken-app.md path.
copyFileSync(source, join(siteDir, "create-pantoken-app.md"));

console.log("✓ staged create-pantoken-app skill to ai/create-pantoken-app-site/");
"}

